"""Self-contained studio, bundled with the Python desktop and web runtime."""

RESEARCH_UI_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NIDM · Research Studio</title><style>
:root{color-scheme:light;--paper:#faf9f6;--ink:#263a33;--muted:#727c75;--line:#e0e4dc;--green:#315a46;--soft:#eaf0e7;--serif:Georgia,'Times New Roman',serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.6 system-ui,sans-serif}button,input,textarea,select{font:inherit}button,a,select{touch-action:manipulation}button{cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible,textarea:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #8aa990;outline-offset:3px}button:disabled{opacity:.5;cursor:wait}[hidden]{display:none!important}.shell{display:grid;grid-template-columns:238px minmax(0,1fr);min-height:100vh}.sidebar{padding:28px 20px;background:#f0f2ec;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:25px}.brand{display:flex;gap:12px;align-items:center;font-size:22px;font-weight:650;letter-spacing:-1px}.mark{display:grid;place-items:center;width:36px;height:36px;background:var(--green);color:white;border-radius:12px;font-size:23px}.brand small{display:block;font:10px system-ui;letter-spacing:2px;color:var(--muted)}.new{background:white;border:1px solid #cbd5c8;border-radius:9px;padding:11px;text-align:left;color:var(--ink)}nav{display:grid;gap:5px}nav a{padding:10px 12px;border-radius:8px;color:#647267}nav a:hover,nav a.active{background:#e1e8dd;color:#254d36}nav a span{display:inline-block;width:26px}.label{font-size:10px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted)}#history{display:grid;gap:5px;margin-top:12px}#history button{border:0;background:transparent;text-align:left;padding:8px;border-radius:6px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:195px}#history button:hover{background:#e1e8dd}.sidefoot{margin-top:auto;font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:18px}.sidefoot strong{display:block;color:var(--ink)}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 38px;gap:15px}.breadcrumb{color:var(--muted);font-size:12px}.breadcrumb b{color:var(--ink);font-weight:500}.badge{font-size:11px;background:var(--soft);padding:5px 10px;border:1px solid #dce4d8;border-radius:20px;white-space:nowrap}.dot{color:#618565}.content{max-width:1090px;margin:auto;padding:46px 48px 24px}.eyebrow{color:#68816c;text-transform:uppercase;letter-spacing:2.2px;font-size:10px;font-weight:600}.hero{max-width:780px;margin:18px auto 32px}.hero h1{font:normal clamp(36px,4vw,55px)/1.13 var(--serif);letter-spacing:-1.8px;margin:14px 0 18px}.hero h1 em{color:#688267;font-weight:normal}.hero p{color:var(--muted);font-size:15px;max-width:530px;margin:0}.intro-icon{float:right;width:135px;height:125px;opacity:.72;margin-top:5px}.composer{background:white;border:1px solid #d6ddd1;border-radius:17px;box-shadow:0 8px 35px #263a3307;overflow:hidden}.composer label.source-label{display:block;margin:19px 22px 0;color:var(--muted);font-size:11px}textarea{width:100%;min-height:123px;resize:vertical;border:0;padding:12px 22px;color:var(--ink);background:transparent;outline-offset:-4px!important;line-height:1.7}textarea::placeholder{color:#9bA299}.composebar{display:flex;gap:10px;align-items:center;justify-content:space-between;border-top:1px solid #eef0eb;padding:12px 16px}.composebar select{border:0;background:#f1f4ee;border-radius:7px;padding:7px;color:var(--ink);max-width:220px}.primary{background:var(--green);color:white;border:0;border-radius:8px;padding:9px 17px}.secondary{border:1px solid var(--line);border-radius:7px;padding:8px 12px;background:white;color:var(--ink)}.fine{color:var(--muted);font-size:11px;margin:10px 4px}.options{padding:12px 22px;display:flex;flex-wrap:wrap;gap:20px;border-top:1px solid var(--line);font-size:12px}.options input{width:72px;margin-left:8px;border:1px solid var(--line);border-radius:5px;padding:4px}.section-heading{display:flex;justify-content:space-between;align-items:center;margin:35px 0 14px;font-size:12px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{display:block;text-align:left;background:transparent;border:1px solid var(--line);border-radius:11px;padding:19px;color:var(--ink);transition:background .15s,transform .15s}.card:hover{background:#edf1e8;transform:translateY(-2px)}.card .symbol{font-size:21px;color:#708567}.card strong{display:block;font-size:13px;font-weight:550;margin:13px 0 7px}.card p{margin:0;color:var(--muted);font-size:12px;line-height:1.65}.footer{display:flex;justify-content:center;gap:8px;margin:36px 0;color:#8b938a;font-size:10px;letter-spacing:.3px}.run-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.run-header h2{font:30px var(--serif);margin:0}.run-grid{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:20px}.panel{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:15px}.panel h3{font-size:12px;font-weight:550;margin:0 0 14px}.source{font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:160px;overflow:auto;color:var(--muted)}.timeline{list-style:none;padding:0;margin:0}.timeline li{padding:10px 0;display:flex;align-items:center;gap:10px;font-size:12px}.state{width:19px;height:19px;display:grid;place-items:center;border-radius:50%;background:#eff2ec;color:#7a8475;font-size:10px}.completed .state{background:#dfeddf;color:#386446}.running .state{background:#e7d9b4;color:#776326}.running{font-weight:600}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.metric{padding:15px;border-radius:8px;background:#f4f6f0}.metric b{font:30px var(--serif);display:block}.metric span{color:var(--muted);font-size:11px}#themes{font-size:12px;color:#54714e;margin:16px 0}.notice{border-left:2px solid #c4b58c;padding-left:12px;color:#77715f;font-size:12px}.download{width:100%;margin-top:8px;text-align:left}.artifact-icon{font-size:24px;color:#688267}.chart{width:100%;height:150px;margin:12px 0}.legend{font-size:11px;color:var(--muted)}.error{padding:12px;border-radius:7px;background:#f5e9e4;color:#8c4030}details{font-size:12px}details pre{max-height:300px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}.capabilities{display:grid;gap:10px;font-size:12px}.capabilities div{display:flex;justify-content:space-between;gap:8px}.capabilities span{color:var(--muted)}.mobile-brand{display:none}#status{font-size:12px;color:var(--muted);margin-bottom:15px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(min-width:1450px){.content{padding-top:65px}}@media(max-width:1050px){.shell{grid-template-columns:200px 1fr}.sidebar{padding:25px 15px}.content{padding:28px}#history button{width:160px}.run-grid{grid-template-columns:1fr}.artifact-panel{display:grid;grid-template-columns:1fr 1fr;gap:15px}.intro-icon{width:95px}.topbar{padding:0 28px}}@media(max-width:700px){.shell{display:block}.sidebar{display:none}.mobile-brand{display:inline}.topbar{height:60px;padding:0 18px}.content{padding:25px 18px}.hero{margin:12px 0 26px}.hero h1{font-size:39px}.intro-icon{display:none}.cards{grid-template-columns:1fr}.card{padding:16px}.card strong{margin:6px 0}.section-heading{margin-top:26px}.composebar{flex-wrap:wrap}.artifact-panel{display:block}.footer{flex-wrap:wrap}.breadcrumb{font-size:11px}}
#workspace{max-width:100%;padding:7px 10px;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink)}#mobile-history button{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#mobile-history{min-width:0}#saved-list{margin-top:10px}</style></head><body><div class="shell">
<aside class="sidebar"><a class="brand" href="/" aria-label="NIDM Research Studio home"><span class="mark">n</span><div>NIDM<small>RESEARCH STUDIO</small></div></a>
<button class="new" id="new">＋ &nbsp; New exploration</button><nav aria-label="Main navigation"><a class="active" href="/" aria-current="page"><span>◈</span> Research studio</a><a href="/workbench"><span>▦</span> Research workbench</a><a href="/academy"><span>⌘</span> Learning academy</a><a href="/manual"><span>▤</span> Field guide</a></nav>
<section><div class="label">Explorations</div><div id="history"><p class="fine">Your explorations will appear here.</p></div></section><div class="sidefoot"><strong>Evidence before influence.</strong>Built for thoughtful research.<br>Local tools · Open source</div></aside>
<main><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">NIDM / </span>Workspace &nbsp; / &nbsp; <b>Research studio</b></div><span class="badge"><span class="dot">●</span> &nbsp; Offline research tools</span></header>
<div class="content"><div class="panel"><label for="workspace">Save explorations in </label><select id="workspace"><option value="">This tab only (unsaved)</option></select><p class="fine" id="storage-note">Unsaved explorations clear on refresh.</p><div id="history-error" role="alert" class="error" hidden></div><details id="saved-list"><summary>Browse explorations</summary><div id="mobile-history"></div><button class="secondary" id="more-history" hidden>Load more</button></details></div><section id="welcome"><div class="hero"><svg class="intro-icon" viewBox="0 0 140 130" fill="none" aria-hidden="true"><path d="M15 97Q40 43 67 88Q91 20 128 97M15 109Q65 91 128 109M37 91Q53 65 68 91" stroke="#9caa91" stroke-width="1.4"/><circle cx="99" cy="29" r="12" stroke="#acb59b"/><path d="M70 100V38M70 67Q43 67 48 45Q70 44 70 67M70 52Q91 53 94 33Q71 32 70 52" stroke="#708a6a" stroke-width="1.4"/></svg><div class="eyebrow">A clearer path from evidence to insight</div><h1>Every narrative holds<br><em>something to discover.</em></h1><p>Explore the stories shaping change. Make sense of evidence, test assumptions, and build research you can trace.</p></div>
<form id="composer" class="composer"><label class="source-label" for="prompt">What narrative would you like to explore?</label><textarea id="prompt" minlength="20" maxlength="20000" required placeholder="Paste a field note, interview excerpt, or community narrative…"></textarea><div class="options" id="scenario-options" hidden><label>Days <input id="days" type="number" min="7" max="365" value="90" required></label><label>Intervention strength <input id="strength" type="number" min="0" max="1" step="0.05" value="0.3" required></label></div><div class="composebar"><label><span class="sr-only">Research skill</span><select id="skill"><option value="evidence">◈ &nbsp; Understand a narrative</option><option value="scenario">↗ &nbsp; Explore a scenario</option></select></label><button class="primary" id="submit" type="submit">Explore &nbsp; ↑</button></div></form><p class="fine">English heuristic analysis · Processed by this server, without remote AI calls · Choose a workspace above to keep completed runs.</p>
<div class="section-heading"><span>Start with a direction</span><span>Made for curious minds ↙</span></div><div class="cards"><button class="card" id="example"><span class="symbol">◈</span><strong>Understand a narrative ↗</strong><p>Try a sample field note. Explore themes, trust, and barriers to adoption.</p></button><button class="card" id="scenario-example"><span class="symbol">⌁</span><strong>Ask “what if?” ↗</strong><p>Compare a baseline with an illustrative intervention scenario.</p></button><a class="card" href="/workbench"><span class="symbol">▦</span><strong>Work with your evidence ↗</strong><p>Open ingestion, review, modelling, and exports in the research workbench.</p></a></div></section>
<section id="run" hidden aria-label="Research exploration"><div class="run-header"><h2>Your exploration</h2><button class="secondary" id="another">New exploration ＋</button></div><div id="status" role="status" aria-live="polite"></div><div id="error" class="error" role="alert" hidden></div><div class="run-grid"><div><div class="panel"><h3>YOUR EVIDENCE</h3><div id="source" class="source"></div></div><div class="panel"><h3>RESEARCH PATH <span class="fine">· Deterministic workflow</span></h3><ol class="timeline" id="steps"></ol><button class="secondary" id="stop">Stop exploration</button></div><div id="findings" hidden><div class="panel"><h3>Heuristic signals</h3><div class="metrics"><div class="metric"><b id="trust"></b><span>Trust signal / 1</span></div><div class="metric"><b id="barrier"></b><span>Adoption barrier / 1</span></div></div><p id="themes"></p><p class="notice" id="caveat"></p></div><div class="panel" id="scenario-result" hidden><h3>Illustrative adoption trajectories</h3><svg id="chart" class="chart" viewBox="0 0 500 150" role="img" aria-label="Baseline and intervention adoption trajectories, proportions from zero to one"></svg><p id="comparison" class="legend"></p></div><div class="panel"><details><summary>Inspect tool outputs and assumptions</summary><pre id="raw"></pre></details></div></div></div><aside class="artifact-panel"><div class="panel"><span class="artifact-icon">▤</span><h3>Research artifacts</h3><p class="fine" id="artifact-note">Your brief and reproducible results will appear when the workflow completes.</p><button id="brief" class="secondary download" disabled>↓ &nbsp; Evidence brief .md</button><button id="json" class="secondary download" disabled>↓ &nbsp; Research bundle .json</button><button id="delete-run" class="secondary download" hidden>Delete saved exploration</button></div><div class="panel"><h3>Execution context</h3><div class="capabilities"><div>Domain tools <span>Local</span></div><div>Evidence review <span>Required</span></div><div>Run history <span id="history-context">This tab</span></div><div>Remote AI <span>Not used</span></div></div><p class="fine">No evidence is committed to your ledger automatically.</p></div></aside></div></section><footer class="footer"><span>NARRATIVE DIFFUSION & INOCULATION MODEL</span><span>·</span><a href="/manual">Grounded in evidence. Open to discovery.</a></footer></div></main></div>
<script>
const $=id=>document.getElementById(id);
const labels={encode:'Identify narrative signals',diagnose:'Inspect inoculation signals',simulate:'Compare model scenarios',brief:'Prepare a traceable brief'};
const sample='Sample field note: A parent in Musanze says the improved stove produces less smoke, but the price is too expensive. She would trust a demonstration from a trained health worker before deciding to try it.';
let controller=null,current=null,history=[],generation=0,sessionHistory=[],historyToken=0;
function chooseScenario(){ $('scenario-options').hidden=$('skill').value!=='scenario'; }
$('skill').onchange=chooseScenario;
function example(skill){$('skill').value=skill;chooseScenario();$('prompt').value=sample;$('prompt').focus();}
$('example').onclick=()=>example('evidence');$('scenario-example').onclick=()=>example('scenario');
function reset(){generation++;if(controller)controller.abort();controller=null;current=null;$('delete-run').hidden=true;$('run').hidden=true;$('welcome').hidden=false;$('prompt').focus();}
$('new').onclick=reset;$('another').onclick=reset;
function setSteps(steps){$('steps').replaceChildren();steps.forEach(tool=>{const li=document.createElement('li');li.id='step-'+tool;const icon=document.createElement('span');icon.className='state';icon.textContent='·';const label=document.createElement('span');label.textContent=labels[tool]||tool;li.append(icon,label);$('steps').append(li);});}
function updateStep(tool,status){const li=$('step-'+tool);if(!li)return;li.className=status;li.firstChild.textContent=status==='completed'?'✓':status==='running'?'↻':'·';}
function drawScenario(s){$('chart').replaceChildren();if(!s)return;const ns='http://www.w3.org/2000/svg';[0,0.5,1].forEach(value=>{const line=document.createElementNS(ns,'line');line.setAttribute('x1','30');line.setAttribute('x2','490');line.setAttribute('y1',135-value*120);line.setAttribute('y2',135-value*120);line.setAttribute('stroke','#e4e8df');$('chart').append(line);const text=document.createElementNS(ns,'text');text.setAttribute('x','0');text.setAttribute('y',139-value*120);text.setAttribute('fill','#778171');text.setAttribute('font-size','10');text.textContent=value;$('chart').append(text);});['baseline','intervention'].forEach((key,index)=>{const p=document.createElementNS(ns,'polyline');p.setAttribute('points',s[key].map((row,i)=>`${30+i/(s[key].length-1)*460},${135-row.adoption*120}`).join(' '));p.setAttribute('fill','none');p.setAttribute('stroke',index?'#315a46':'#b6bcae');p.setAttribute('stroke-width','2.5');$('chart').append(p);});$('comparison').textContent=`${s.horizon_days} days · Baseline (grey): ${(s.baseline.at(-1).adoption*100).toFixed(1)}% · Intervention (green): ${(s.intervention.at(-1).adoption*100).toFixed(1)}%. Illustrative outputs, not forecasts.`;}
function showResult(result){current=result;$('delete-run').hidden=!result.workspace_id;$('findings').hidden=false;$('trust').textContent=result.encoding.trust_score.toFixed(2);$('barrier').textContent=result.encoding.adoption_barrier_score.toFixed(2);$('themes').textContent='Detected themes · '+result.encoding.themes.join(' · ');$('caveat').textContent=result.caveat;$('raw').textContent=JSON.stringify({encoding:result.encoding,diagnosis:result.diagnosis,scenario:result.scenario},null,2);$('scenario-result').hidden=!result.scenario;drawScenario(result.scenario);$('brief').disabled=false;$('json').disabled=false;$('artifact-note').textContent='Draft · Requires researcher review. Includes source evidence.';$('status').textContent='Exploration complete · Review the signals and assumptions below.';$('stop').hidden=true;}
function showHistoryError(error){$('history-error').hidden=false;$('history-error').textContent=error.message;}
async function jsonRequest(url,options){const response=await fetch(url,options);if(!response.ok)throw Error(`Workspace service returned ${response.status}. Please retry.`);return response.status===204?null:response.json();}
function runURL(workspace,id){return `/research/workspaces/${encodeURIComponent(workspace)}/runs${id?'/'+encodeURIComponent(id):''}`;}
function renderHistory(){for(const container of ['history','mobile-history']){$(container).replaceChildren();history.forEach(row=>{const b=document.createElement('button');b.className='secondary download';b.textContent=row.title||row.source.text.slice(0,45);b.onclick=async()=>{const workspace=$('workspace').value;const token=++generation;if(controller)controller.abort();controller=null;try{const result=workspace?await jsonRequest(runURL(workspace,row.run_id)):row;if(token!==generation)return;$('welcome').hidden=true;$('run').hidden=false;$('error').hidden=true;$('source').textContent=result.source.text;setSteps(result.scenario?['encode','diagnose','simulate','brief']:['encode','diagnose','brief']);Object.keys(labels).forEach(tool=>updateStep(tool,'completed'));showResult(result);}catch(error){if(token===generation)showHistoryError(error);}};$(container).append(b);});}}
async function refreshHistory(append=false){const token=++historyToken;const workspace=$('workspace').value;$('history-error').hidden=true;$('more-history').hidden=true;if(!workspace){history=[...sessionHistory];renderHistory();return;}try{const data=await jsonRequest(runURL(workspace)+`?offset=${append?history.length:0}&limit=50`);if(token!==historyToken)return;history=append?history.concat(data.runs):data.runs;renderHistory();$('more-history').hidden=history.length>=data.total;}catch(error){if(token===historyToken)showHistoryError(error);}}
$('more-history').onclick=()=>refreshHistory(true);
$('workspace').onchange=()=>{reset();history=[];renderHistory();const saved=!!$('workspace').value;$('storage-note').textContent=saved?'Completed runs and source evidence are saved on this server until you delete them. Everyone with access to this app instance can access its workspaces.':'Unsaved explorations clear on refresh.';$('history-context').textContent=saved?'Workspace':'This tab';refreshHistory();};
async function loadWorkspaces(){try{const data=await jsonRequest('/workspaces');for(const workspace of data.workspaces){const option=document.createElement('option');option.value=workspace.workspace_id;option.textContent=workspace.name;$('workspace').append(option);}}catch(error){showHistoryError(error);}}
$('delete-run').onclick=async()=>{if(!current?.workspace_id)return;if(!confirm('Delete this saved exploration and its artifacts? Existing downloaded copies and backups will remain.'))return;const result=current;const token=generation;$('delete-run').disabled=true;try{await jsonRequest(runURL(result.workspace_id,result.run_id),{method:'DELETE'});if(token===generation){reset();await refreshHistory();}}catch(error){if(token===generation)showHistoryError(error);}finally{$('delete-run').disabled=false;}};
loadWorkspaces();
function download(kind){if(!current)return;const text=kind==='brief'?current.brief:JSON.stringify(current,null,2);const blob=new Blob([text],{type:kind==='brief'?'text/markdown;charset=utf-8':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`nidm-${current.run_id}.${kind==='brief'?'md':'json'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('brief').onclick=()=>download('brief');$('json').onclick=()=>download('json');
$('stop').onclick=()=>{if(controller)controller.abort();};
$('composer').onsubmit=async event=>{event.preventDefault();const text=$('prompt').value.trim();if(text.length<20){$('prompt').setCustomValidity('Please provide at least 20 characters of narrative evidence.');$('prompt').reportValidity();return;}
const token=++generation;controller=new AbortController();current=null;$('delete-run').hidden=true;const workspace=$('workspace').value;let received=false;$('welcome').hidden=true;$('run').hidden=false;$('findings').hidden=true;$('error').hidden=true;$('stop').hidden=false;$('brief').disabled=true;$('json').disabled=true;$('artifact-note').textContent='Preparing your research artifacts…';$('source').textContent=text;$('status').textContent='Running local research tools…';setSteps([]);
try{const response=await fetch('/research/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,workspace_id:workspace||null,skill:$('skill').value,horizon_days:Number($('days').value),intervention_strength:Number($('strength').value)}),signal:controller.signal});if(!response.ok)throw Error(response.status===422?'Check the evidence and scenario parameters, then retry.':`Research service returned ${response.status}. Please retry.`);
const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';function consume(line){if(!line.trim()||token!==generation)return;const item=JSON.parse(line);if(item.type==='plan')setSteps(item.steps);if(item.type==='step')updateStep(item.tool,item.status);if(item.type==='error')throw Error(item.message);if(item.type==='result'){received=true;showResult(item.result);if(workspace){refreshHistory();}else{sessionHistory.unshift(item.result);history=[...sessionHistory];renderHistory();}}}
while(true){const {value,done}=await reader.read();if(token!==generation){await reader.cancel();return;}buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop();lines.forEach(consume);if(done){consume(buffer);break;}}
if(!received)throw Error('The connection ended before results arrived. Start a new exploration to retry.');
}catch(error){if(token!==generation)return;const stopped=error.name==='AbortError';$('status').textContent=stopped?'Exploration stopped. No evidence was committed.':'Exploration could not finish.';$('artifact-note').textContent='No completed artifacts. Your source remains above.';document.querySelectorAll('.running').forEach(li=>{li.className='';li.firstChild.textContent='–';});if(!stopped){$('error').hidden=false;$('error').textContent=error.message;}}finally{if(token===generation){controller=null;$('stop').hidden=true;}}};
$('prompt').oninput=()=>$('prompt').setCustomValidity('');
</script></body></html>'''
